INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("人助け、応援", "A", "獣人族", 27, 8, 0, 16, "ヒヨリ", "トゥインクルウィッシュ", 44, 155, 100101, 2, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助けが大好き！　前向き格闘娘", "東山奈央");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("料理、人間観察", "O", "ヒューマン", 5, 4, 0, 17, "ユイ", "トゥインクルウィッシュ", 47, 158, 100201, 2, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "戦闘のサポートが得意な、心優しい少女", "種田梨沙");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書、乗馬、お茶", "B", "魔族", 12, 1, 0, 18, "レイ", "トゥインクルウィッシュ", 46, 163, 100301, 2, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "クールで何事にも真っ直ぐな剣士", "早見沙織");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("いたずら、探検", "O", "ヒューマン", 10, 8, 0, 9, "ミソギ", "リトルリリカル", 27, 128, 100401, 5, "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "探検好きのイタズラっ子", "諸星すみれ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒーローごっこ", "O", "獣人族", 25, 11, 0, 12, "マツリ", "王宮騎士団（NIGHTMARE）", 40, 146, 100501, 8, "？？？", "ヒーローに憧れる騎士見習いの少女", "下田麻美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("サックス", "O", "魔族", 22, 11, 0, 13, "アカリ", "悪魔偽王国軍（ディアボロス）", 42, 150, 100601, 7, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "甘え上手なみんなの人気者", "浅倉杏美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("プリンを食べること", "B", "魔族", 23, 1, 0, 14, "ミヤコ", "悪魔偽王国軍（ディアボロス）", 32, 130, 100701, 7, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "プリン大好きゴースト娘", "雨宮天");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("鏡で自分を見ること", "AB", "エルフ", 10, 10, 0, 14, "ユキ", "ヴァイスフリューゲル　ランドソル支部", 40, 150, 100801, 15, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "ボクは誰よりも美しい", "大空直美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("小説執筆", "A", "魔族", 5, 7, 0, 17, "アンナ", "トワイライトキャラバン", 45, 159, 100901, 13, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "前世を信じる中二病患者、「疾風の冥姫」", "髙野麻美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("空想、ぬいぐるみ集め", "O", "獣人族", 22, 9, 0, 16, "マホ", "自警団（カォン）", 42, 155, 101001, 10, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "マホマホ王国のプリンセス", "内田真礼");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("お裁縫", "A", "ヒューマン", 25, 8, 0, 15, "リノ", "ラビリンス", 44, 156, 101101, 3, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "人懐っこくてマシンガントークな妹系少女", "阿澄佳奈");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("妹と遊ぶこと、二度寝、昼寝、早寝", "A", "エルフ", 24, 12, 0, 17, "ハツネ", "フォレスティエ", 46, 156, 101201, 6, "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "みんなのために超能力を使う眠り姫", "大橋彩香");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書、魔法", "O", "魔族", 21, 8, 0, 18, "ナナカ", "トワイライトキャラバン", 55, 166, 101301, 13, "", "オタク全開な魔法少女", "佳村はるか");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書、推理", "AB", "獣人族", 3, 11, 0, 15, "カスミ", "自警団（カォン）", 41, 152, 101401, 10, "test", "頭脳明晰な美少女名探偵", "水瀬いのり");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("絵本作り", "O", "エルフ", 5, 9, 0, 21, "ミサト", "フォレスティエ", 54, 165, 101501, 6, "test", "母性溢れる優しいみんなの「ミサト先生」", "國府田マリ子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ファッション", "O", "魔族", 10, 4, 0, 17, "スズナ", "ルーセント学院", 48, 167, 101601, 14, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "天真爛漫で人気者のカリスマモデル", "上坂すみれ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("踊り、空手", "A", "獣人族", 7, 7, 0, 17, "カオリ", "自警団（カォン）", 53, 158, 101701, 10, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "いつでも「なんくるないさ～」な天然娘", "高森奈津美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "B", "魔族", 14, 8, 0, 23, "イオ", "ルーセント学院", 52, 162, 101801, 14, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "多くの男性を魅了する無垢な女教師", "伊藤静");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("かわいいもの集め", "O", "獣人族", 3, 4, 0, 10, "ミミ", "リトルリリカル", 21, 117, 102001, 5, "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "お歌もにんじんも、ウサギさんも大好き♪", "日高里菜");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("観劇、おままごと", "B", "ヒューマン", 9, 6, 0, 12, "クルミ", "サレンディア救護院", 40, 150, 102101, 9, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "泣き虫で臆病な守ってあげたい女の子", "植田佳奈");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ゲーム全般", "O", "魔族", 22, 11, 0, 13, "ヨリ", "悪魔偽王国軍（ディアボロス）", 40, 150, 102201, 7, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "人見知りであまのじゃくな女の子", "原紗友里");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("屋内でできる遊び", "B", "ヒューマン", 10, 5, 0, 14, "アヤネ", "サレンディア救護院", 38, 148, 102301, 9, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "ぷうきちといつも一緒！", "芹澤優");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ご奉仕", "O", "ヒューマン", 12, 12, 0, 15, "スズメ", "サレンディア救護院", 43, 154, 102501, 9, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "お嬢さまのためにがんばるドジっ娘メイド", "悠木碧");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("あんパン", "B", "獣人族", 1, 1, 0, 17, "リン", "牧場（エリザベスパーク）", 42, 144, 102601, 11, "test", "遊びと睡眠が何より大事なぐうたら娘", "小岩井ことり");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("実験、裁縫、料理", "B", "魔族", 30, 7, 0, 16, "エリコ", "トワイライトキャラバン", 43, 154, 102701, 13, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "運命の相手に一途すぎる乙女", "橋本ちなみ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("経営、お茶会", "A", "エルフ", 4, 10, 0, 17, "サレン", "サレンディア救護院", 43, 156, 102801, 9, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "救護院を経営する優しい庶民派お嬢様", "堀江由衣");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("舞台鑑賞、ダンス", "B", "ヒューマン", 24, 1, 0, 17, "ノゾミ", "カルミナ", 40, 157, 102901, 4, "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", "歌って踊れる大人気アイドル", "日笠陽子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("忍法開発", "O", "ヒューマン", 31, 8, 0, 16, "ニノン", "ヴァイスフリューゲル　ランドソル支部", 51, 163, 103001, 15, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "トーゴクの神秘、オシエテクダサイ！", "佐藤聡美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("占い", "AB", "魔族", 22, 12, 0, 18, "シノブ", "悪魔偽王国軍（ディアボロス）", 42, 157, 103101, 7, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占いが得意な霊能少女", "大坪由佳");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("慈善事業", "AB", "ヒューマン", 12, 3, 0, 18, "アキノ", "メルクリウス財団", 45, 157, 103201, 12, "この私とともにいる限り、\nお金に不自由はさせませんわ！", "一人前の商人を目指すパワフルお嬢様", "松嵜麗");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("漫才", "B", "ヒューマン", 3, 3, 0, 20, "マヒル", "牧場（エリザベスパーク）", 35, 142, 103301, 11, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "みんなを笑顔にするお笑い牧場主", "新田恵海");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ウインドーショッピング", "A", "エルフ", 16, 3, 0, 22, "ユカリ", "メルクリウス財団", 55, 164, 103401, 12, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "純情でほっとけない大人の女性", "今井麻美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("お勉強", "A", "エルフ", 2, 2, 0, 8, "キョウカ", "リトルリリカル", 21, 118, 103601, 5, "test", "礼儀正しくしっかり者のちびっ子優等生", "小倉唯");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("剣術、年長者をからかう", "A", "ヒューマン", 11, 8, 0, 13, "トモ", "王宮騎士団（NIGHTMARE）", 43, 149, 103701, 8, "test", "義理堅くてからかい好きな剣術少女", "茅原実里");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書、お散歩", "A", "獣人族", 3, 11, 0, 14, "シオリ", "牧場（エリザベスパーク）", 40, 153, 103801, 11, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "読書が趣味の病弱少女", "小清水亜美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("友達作りのイメトレ", "AB", "エルフ", 6, 6, 0, 13, "アオイ", "フォレスティエ", 44, 158, 104001, 6, "友達ができるその日まで…\nBB団で\nトレーニングですっ！", "「友達」に憧れる、エルフの森の女の子", "花澤香菜");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("各種楽器", "O", "ヒューマン", 3, 6, 0, 17, "チカ", "カルミナ", 46, 163, 104201, 4, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "人々を守るために歌う、唱喚士の少女", "福原綾香");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("お菓子作り", "O", "獣人族", 9, 8, 0, 17, "マコト", "自警団（カォン）", 54, 168, 104301, 10, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "男勝りで情に厚いワイルド娘", "小松未可子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("世界征服", "A", "魔族", 5, 5, 0, "??", "イリヤ", "悪魔偽王国軍（ディアボロス）", 50, 172, 104401, 7, "test", "かつては夜を支配した最強の吸血鬼", "丹下桜");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("小説を読むこと", "AB", "ヒューマン", 19, 11, 0, 18, "クウカ", "ヴァイスフリューゲル　ランドソル支部", 49, 157, 104501, 15, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "妄想大好き！　ほんとは照れ屋な女の子", "長妻樹里");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("猫とたわむれること", "AB", "獣人族", 1, 3, 0, 19, "タマキ", "メルクリウス財団", 48, 158, 104601, 12, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "弱きを助け強きをくじく猫娘", "沼倉愛美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("格闘技、湯浴み", "A", "ヒューマン", 25, 10, 0, 25, "ジュン", "王宮騎士団（NIGHTMARE）", 50, 171, 104701, 8, "？？？", "素顔を見せない冷静沈着な女性騎士", "川澄綾子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("傭兵などのアルバイト", "O", "ヒューマン", 11, 11, 0, 20, "ミフユ", "メルクリウス財団", 49, 163, 104801, 12, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "仕事も私事も効率優先な傭兵少女", "田所あずさ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("家事全般", "O", "ヒューマン", 24, 10, 0, 18, "シズル", "ラビリンス", 54, 168, 104901, 3, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "お姉ちゃんがお世話してあげるからねっ！", "生天目仁美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ファッション誌鑑賞、コスメ集め", "A", "魔族", 3, 1, 0, 11, "ミサキ", "ルーセント学院", 22, 120, 105001, 14, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ちょっとおませな恋に恋する女の子", "久野美咲");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("研究、実験", "A", "ヒューマン", 7, 3, 0, 27, "ミツキ", "トワイライトキャラバン", 53, 166, 105101, 13, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "実験が趣味の危険な科学者", "三石琴乃");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("毛繕い、お喋り", "A", "獣人族", 14, 3, 0, 17, "リマ", "牧場（エリザベスパーク）", 100, 150, 105201, 11, "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "乙女チックなもふもふアニマル", "徳井青空");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("お菓子屋通い", "A", "ヒューマン", 28, 7, 0, 17, "モニカ", "ヴァイスフリューゲル　ランドソル支部", 33, 140, 105301, 15, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "見た目も中身もお子ちゃまな異国の軍人", "辻あゆみ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("裁縫", "AB", "ヒューマン", 7, 9, 0, 14, "ツムギ", "カルミナ", 45, 153, 105401, 4, "test", "ファッション大好きなキュートガール", "木戸衣吹");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("観察", "O", "エルフ", 7, 4, 0, 16, "アユミ", "ヴァイスフリューゲル　ランドソル支部", 43, 155, 105501, 15, "test", "どこまでも一途に慕う、純情乙女", "大関英里");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("釣り", "B", "ヒューマン", 11, 7, 0, 25, "ルカ", "トワイライトキャラバン", 54, 167, 105601, 13, "test", "人情味溢れる粋でいなせな「姉御」", "佐藤利奈");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("冒険、おしゃべり", "O", "ヒューマン", 10, 3, 0, 17, "ジータ", "？？？", 45, 156, 105701, "", "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", "空への冒険を夢見る騎空士の少女", "金元寿子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("食べ歩き、料理", "O", "ヒューマン", 31, 3, 0, 17, "ペコリーヌ", "美食殿", 46, 156, 105801, 1, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "いつも元気な腹ペコ少女", "M・A・O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("瞑想、動植物の飼育", "B", "エルフ", 11, 5, 0, 11, "コッコロ", "美食殿", 35, 140, 105901, 1, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "主を慕う、小さなガイド役", "伊藤美来");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("猫と遊ぶ", "A", "獣人族", 2, 9, 0, 14, "キャル", "美食殿", 39, 152, 106001, 1, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "行き倒れの謎のネコミミ魔法使い", "立花理香");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("冒険、思い出話", "O", "ヒューマン", 11, 8, 0, 16, "ムイミ", "？？？", 40, 148, 106101, "", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "さまよえる謎の少女", "潘めぐみ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("キレイな葉っぱを集めること", "O", "エルフ", 17, 6, 0, 15, "アリサ", "？？？", 42, 155, 106301, "", "", "森番を目指すエルフの少女", "優木かな");
