INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("絵画、読書", "O", "ドラゴン族", 17, 4, 0, 25, "ホマレ", "ドラゴンズネスト", "???", 168, 106701, 17, "", "妖しい微笑で全てを見透かす臥竜の頭領", "大西沙織");
