INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("強敵との闘争", "O", "ヒューマン", 7, 2, 0, 27, "クリスティーナ", "王宮騎士団（NIGHTMARE）", "??", 165, 107101, 8, "", "傍若無人な王宮騎士団副団長", "たかはし智秋");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("食べ歩き、料理", "O", "ヒューマン", 31, 3, 0, 17, "ペコリーヌ（サマー）", "美食殿", 46, 156, 107501, 1, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "いつも元気な腹ペコ少女", "M・A・O");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("瞑想、動植物の飼育", "B", "エルフ", 11, 5, 0, 11, "コッコロ（サマー）", "美食殿", 35, 140, 107601, 1, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "主を慕う、小さなガイド役", "伊藤美来");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ご奉仕", "O", "ヒューマン", 12, 12, 0, 15, "スズメ（サマー）", "サレンディア救護院", 43, 154, 107701, 9, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "お嬢さまのためにがんばるドジっ娘メイド", "悠木碧");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("猫と遊ぶ", "A", "獣人族", 2, 9, 0, 14, "キャル（サマー）", "美食殿", 39, 152, 107801, 1, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "行き倒れの謎のネコミミ魔法使い", "立花理香");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("猫とたわむれること", "AB", "獣人族", 1, 3, 0, 19, "タマキ（サマー）", "メルクリウス財団", 48, 158, 107901, 12, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "弱きを助け強きをくじく猫娘", "沼倉愛美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("傭兵などのアルバイト", "O", "ヒューマン", 11, 11, 0, 20, "ミフユ（サマー）", "メルクリウス財団", 49, 163, 108001, 12, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "仕事も私事も効率優先な傭兵少女", "田所あずさ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("占い", "AB", "魔族", 22, 12, 0, 18, "シノブ（ハロウィン）", "悪魔偽王国軍（ディアボロス）", 42, 157, 108101, 7, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占いが得意な霊能少女", "大坪由佳");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("プリンを食べること", "B", "魔族", 23, 1, 0, 14, "ミヤコ（ハロウィン）", "悪魔偽王国軍（ディアボロス）", 32, 130, 108201, 7, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "プリン大好きゴースト娘", "雨宮天");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ファッション誌鑑賞、コスメ集め", "A", "魔族", 3, 1, 0, 11, "ミサキ（ハロウィン）", "ルーセント学院", 22, 120, 108301, 14, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ちょっとおませな恋に恋する女の子", "久野美咲");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("各種楽器", "O", "ヒューマン", 3, 6, 0, 17, "チカ（クリスマス）", "カルミナ", 46, 163, 108401, 4, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "人々を守るために歌う、唱喚士の少女", "福原綾香");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("観劇、おままごと", "B", "ヒューマン", 9, 6, 0, 12, "クルミ（クリスマス）", "サレンディア救護院", 40, 150, 108501, 9, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "泣き虫で臆病な守ってあげたい女の子", "植田佳奈");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("屋内でできる遊び", "B", "ヒューマン", 10, 5, 0, 14, "アヤネ（クリスマス）", "サレンディア救護院", 38, 148, 108601, 9, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "ぷうきちといつも一緒！", "芹澤優");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("人助け、応援", "A", "獣人族", 27, 8, 0, 16, "ヒヨリ（ニューイヤー）", "トゥインクルウィッシュ", 44, 155, 108701, 2, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助けが大好き！　前向き格闘娘", "東山奈央");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("料理、人間観察", "O", "ヒューマン", 5, 4, 0, 17, "ユイ（ニューイヤー）", "トゥインクルウィッシュ", 47, 158, 108801, 2, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "戦闘のサポートが得意な、心優しい少女", "種田梨沙");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書、乗馬、お茶", "B", "魔族", 12, 1, 0, 18, "レイ（ニューイヤー）", "トゥインクルウィッシュ", 46, 163, 108901, 2, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "クールで何事にも真っ直ぐな剣士", "早見沙織");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("実験、裁縫、料理", "B", "魔族", 30, 7, 0, 16, "エリコ（バレンタイン）", "トワイライトキャラバン", 43, 154, 109001, 13, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "運命の相手に一途すぎる乙女", "橋本ちなみ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("家事全般", "O", "ヒューマン", 24, 10, 0, 18, "シズル（バレンタイン）", "ラビリンス", 54, 168, 109101, 3, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "お姉ちゃんがお世話してあげるからねっ！", "生天目仁美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書", "AB", "ヒューマン", 1, 12, 0, 17, "アン", "？？？", 55, 156, 109201, "", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", "英霊と契約を結んだマナリアの天才王女", "日笠陽子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("食べること、眠ること", "O", "ヒューマン", 4, 2, 0, 16, "ルゥ", "？？？", 45, 144, 109301, "", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", "マナリア魔法学院の新入生", "こやまきみこ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ピアノ", "B", "半人半竜", 3, 11, 0, 17, "グレア", "？？？", 67, 167, 109401, "", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", "人を超越した力を有す心優しい竜姫", "福原綾香");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("小説を読むこと", "AB", "ヒューマン", 19, 11, 0, 18, "クウカ（オーエド）", "ヴァイスフリューゲル　ランドソル支部", 49, 157, 109501, 15, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "妄想大好き！　ほんとは照れ屋な女の子", "長妻樹里");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("忍法開発", "O", "ヒューマン", 31, 8, 0, 16, "ニノン（オーエド）", "ヴァイスフリューゲル　ランドソル支部", 51, 163, 109601, 15, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "トーゴクの神秘、オシエテクダサイ！", "佐藤聡美");
