INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書、魔法", "O", "魔族", 21, 8, 0, 18, "ナナカ（サマー）", "トワイライトキャラバン", 55, 166, 113301, 13, "", "オタク全開な魔法少女", "佳村はるか");
