INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("サックス", "O", "魔族", 22, 11, 0, 13, "アカリ（エンジェル）", "悪魔偽王国軍（ディアボロス）", 42, 150, 113701, 7, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "甘え上手なみんなの人気者", "浅倉杏美");
