INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("空想、ぬいぐるみ集め", "O", "獣人族", 22, 9, 0, 16, "マホ（シンデレラ）", "自警団（カォン）", 42, 155, 116001, 10, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "マホマホ王国のプリンセス", "内田真礼");
