INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("猫とたわむれること", "AB", "獣人族", 1, 3, 0, 19, "タマキ（作業服）", "メルクリウス財団", 48, 158, 116801, 12, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "弱きを助け強きをくじく猫娘", "沼倉愛美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("傭兵などのアルバイト", "O", "ヒューマン", 11, 11, 0, 20, "ミフユ（作業服）", "メルクリウス財団", 49, 163, 116901, 12, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "仕事も私事も効率優先な傭兵少女", "田所あずさ");
