INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("研究、実験", "A", "ヒューマン", 7, 3, 0, 27, "ミツキ（オーエド）", "トワイライトキャラバン", 53, 166, 117501, 13, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "実験が趣味の危険な科学者", "三石琴乃");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("鏡で自分を見ること", "AB", "エルフ", 10, 10, 0, 14, "ユキ（オーエド）", "ヴァイスフリューゲル　ランドソル支部", 40, 150, 117601, 15, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "ボクは誰よりも美しい", "大空直美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("踊り、空手", "A", "獣人族", 7, 7, 0, 17, "カオリ（ハロウィン）", "自警団（カォン）", 53, 158, 117701, 10, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "いつでも「なんくるないさ～」な天然娘", "高森奈津美");
