INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("人間観察", "AB", "ヒューマン", 25, 7, 0, 25, "ラビリスタ（オーバーロード）", "ラビリンス", "??", 160, 121201, 3, "", "秘密結社ラビリンスの『迷宮女王』", "沢城みゆき");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("観劇、おままごと", "B", "ヒューマン", 9, 6, 0, 12, "クルミ（ステージ）", "サレンディア救護院", 40, 150, 121301, 9, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "泣き虫で臆病な守ってあげたい女の子", "植田佳奈");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ファッション誌鑑賞、コスメ集め", "A", "魔族", 3, 1, 0, 11, "ミサキ（ステージ）", "ルーセント学院", 22, 120, 121401, 14, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ちょっとおませな恋に恋する女の子", "久野美咲");
