INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("小説執筆", "A", "魔族", 5, 7, 0, 17, "アンナ（パイレーツ）", "トワイライトキャラバン", 45, 159, 121901, 13, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "前世を信じる中二病患者、「疾風の冥姫」", "髙野麻美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("占い", "AB", "魔族", 22, 12, 0, 18, "シノブ（パイレーツ）", "悪魔偽王国軍（ディアボロス）", 42, 157, 122001, 7, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占いが得意な霊能少女", "大坪由佳");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("友達作りのイメトレ", "AB", "エルフ", 6, 6, 0, 13, "アオイ（キャンプ）", "フォレスティエ", 44, 158, 122101, 6, "", "「友達」に憧れる、エルフの森の女の子", "花澤香菜");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ウインドーショッピング", "A", "エルフ", 16, 3, 0, 22, "ユカリ（キャンプ）", "メルクリウス財団", 55, 164, 122201, 12, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "純情でほっとけない大人の女性", "今井麻美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("お散歩、お料理", "AB", "魔族", 6, 12, 0, "??", "ヴァンピィ", "？？？", 41, 149, 122301, "", "", "けんぞくのご主人様", "釘宮理恵");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("人助け、応援", "A", "獣人族", 27, 8, 0, 16, "ヒヨリ（サマー）", "トゥインクルウィッシュ", 44, 155, 122401, 2, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助けが大好き！　前向き格闘娘", "東山奈央");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書、乗馬、お茶", "B", "魔族", 12, 1, 0, 18, "レイ（サマー）", "トゥインクルウィッシュ", 46, 163, 122501, 2, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "クールで何事にも真っ直ぐな剣士", "早見沙織");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("料理、人間観察", "O", "ヒューマン", 5, 4, 0, 17, "ユイ（サマー）", "トゥインクルウィッシュ", 47, 158, 122601, 2, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "戦闘のサポートが得意な、心優しい少女", "種田梨沙");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("お勉強", "A", "エルフ", 2, 2, 0, 8, "キョウカ（サマー）", "リトルリリカル", 21, 118, 122701, 5, "", "礼儀正しくしっかり者のちびっ子優等生", "小倉唯");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("いたずら、探検", "O", "ヒューマン", 10, 8, 0, 9, "ミソギ（サマー）", "リトルリリカル", 27, 128, 122801, 5, "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "探検好きのイタズラっ子", "諸星すみれ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("かわいいもの集め", "O", "獣人族", 3, 4, 0, 10, "ミミ（サマー）", "リトルリリカル", 21, 117, 122901, 5, "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "お歌もにんじんも、ウサギさんも大好き♪", "日高里菜");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("？？？", "?", "？？？", "?", "?", 0, "??", "アメス", "？？？", "???", 150, 123001, "", "", "新たな姿で騎士の冒険を支え続ける妖精", "相坂優歌");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("空想、ぬいぐるみ集め", "O", "獣人族", 22, 9, 0, 16, "マホ（エクスプローラー）", "自警団（カォン）", 42, 155, 123101, 10, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "マホマホ王国のプリンセス", "内田真礼");
