INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("研究、実験", "A", "ヒューマン", 7, 3, 0, 27, "ミツキ（ニューイヤー）", "トワイライトキャラバン", 53, 166, 124701, 13, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "実験が趣味の危険な科学者", "三石琴乃");
