INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("冒険、思い出話", "O", "ヒューマン", 11, 8, 0, 16, "ムイミ（リベレイター）", "？？？", 40, 148, 125001, "", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "さまよえる謎の少女", "潘めぐみ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("猫とたわむれること", "AB", "獣人族", 1, 3, 0, 19, "タマキ（カフェ）", "メルクリウス財団", 48, 158, 125101, 12, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "弱きを助け強きをくじく猫娘", "沼倉愛美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("お菓子屋通い", "A", "ヒューマン", 28, 7, 0, 17, "モニカ（カフェ）", "ヴァイスフリューゲル　ランドソル支部", 33, 140, 125201, 15, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "見た目も中身もお子ちゃまな異国の軍人", "辻あゆみ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("瞑想、動植物の飼育", "B", "エルフ", 11, 5, 0, 11, "コッコロ（レンジャー）", "美食殿", 35, 140, 125301, 1, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "主を慕う、小さなガイド役", "伊藤美来");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書、お散歩", "A", "獣人族", 3, 11, 0, 14, "シオリ（レンジャー）", "牧場（エリザベスパーク）", 40, 153, 125401, 11, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "読書が趣味の病弱少女", "小清水亜美");
